-- Table structure for table `processo_administrativo_solicitacoes`
--

DROP TABLE IF EXISTS `processo_administrativo_solicitacoes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `processo_administrativo_solicitacoes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `processo_administrativo_id` int unsigned NOT NULL,
  `data_solicitacao` date NOT NULL,
  `expediente` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Protocolo do expediente no SIGADOC',
  `destinatario_lotacao_id` smallint unsigned NOT NULL,
  `assunto` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `prazo` date DEFAULT NULL,
  `status` enum('AGUARDANDO','ATENDIDO','ENCERRADO') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AGUARDANDO',
  `criado_por` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_pas_processo` (`processo_administrativo_id`,`data_solicitacao`),
  KEY `ix_pas_status_prazo` (`status`,`prazo`),
  KEY `ix_pas_destinatario` (`destinatario_lotacao_id`),
  KEY `ix_pas_criado_por` (`criado_por`),
  CONSTRAINT `fk_pas_criado_por` FOREIGN KEY (`criado_por`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pas_destinatario` FOREIGN KEY (`destinatario_lotacao_id`) REFERENCES `lotacoes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pas_processo` FOREIGN KEY (`processo_administrativo_id`) REFERENCES `processos_administrativos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

